import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/booker-tournament-detail-in-progress.DSen7Gbh.js";var i=JSON.parse(`{"title":"Configure Tournaments","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configure-tournaments.md","filePath":"guide/configure-tournaments.md"}`),a={name:`guide/configure-tournaments.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="configure-tournaments" tabindex="-1">Configure Tournaments <a class="header-anchor" href="#configure-tournaments" aria-label="Permalink to &quot;Configure Tournaments&quot;">​</a></h1><p>A booker&#39;s guide to tournaments — one-shot brackets that crown a contender or a champion, and annual editions that run themselves year after year.</p><p><strong>Two kinds of tournament:</strong></p><ul><li><strong>One-time</strong> — a single bracket with an optional host show. When its payoff match books, the tournament is done.</li><li><strong>Recurring (annual)</strong> — pairs with a PLE show template. When a payoff books, the <em>next edition</em> is created automatically and the template pairing re-points to it — no manual re-arming each year.</li></ul><hr><h2 id="step-1-—-create-the-tournament" tabindex="-1">Step 1 — Create the tournament <a class="header-anchor" href="#step-1-—-create-the-tournament" aria-label="Permalink to &quot;Step 1 — Create the tournament&quot;">​</a></h2><p>Open <strong>Tournaments</strong> from the navigation and click <strong>New Tournament</strong>. The wizard has two tabs.</p><h3 id="tab-1-—-details" tabindex="-1">Tab 1 — Details <a class="header-anchor" href="#tab-1-—-details" aria-label="Permalink to &quot;Tab 1 — Details&quot;">​</a></h3><ul><li><strong>Tournament Name</strong> — required. Recurring editions get Roman numerals appended automatically (&quot;Time Vault&quot; → &quot;Time Vault II&quot;).</li><li><strong>Format</strong> — how the bracket is shaped (single elimination, qualifier groups, …). The list comes from the game&#39;s installed formats; each shows its entrant range.</li><li><strong>Linked Championship (optional)</strong> — award a title to the winner. The current champion(s) are automatically excluded from seeding — they can&#39;t win the belt from themselves. If the title has a gender constraint, eligibility respects it.</li><li><strong>Gender Filter (optional)</strong> — restrict entrants to a division (men&#39;s/women&#39;s) even when the tournament isn&#39;t tied to a gendered title. Both constraints apply together.</li><li><strong>Host Show (optional)</strong> — for one-time tournaments: the payoff books on this show exactly once, and the earlier rounds pace automatically onto the weekly shows before it. Picking a host enables the payoff match type and rule pickers.</li><li><strong>Payoff Match Type / Rule (optional)</strong> — the segment type (defaults to One on One) and stipulation for the final.</li><li><strong>Edition Cadence</strong> — leave <strong>One-time</strong>, or choose <strong>Annual</strong> to make the tournament recurring. Annual editions pair with a PLE show template.</li><li><strong>Allowed Segment Rules (optional)</strong> — rules randomly applied to matches; a fixed rule can still be pinned per round later.</li></ul><h3 id="tab-2-—-seeding" tabindex="-1">Tab 2 — Seeding <a class="header-anchor" href="#tab-2-—-seeding" aria-label="Permalink to &quot;Tab 2 — Seeding&quot;">​</a></h3><p>Three ways to fill the bracket:</p><ul><li><strong>Auto (by fan count)</strong> — seeds the top wrestlers by fans. A live <strong>match-up preview</strong> shows the first-round pairings before you commit. The entrant count is capped at the eligible roster (after gender constraints).</li><li><strong>Manual (pick wrestlers)</strong> — hand-pick and order every entrant.</li><li><strong>Don&#39;t seed now (seed later)</strong> — create the empty bracket and seed it from the tournament detail view, or let a paired show template seed it automatically when the show is approved.</li></ul><p>For the <strong>Qualifier Groups</strong> format, an extra field sets wrestlers per qualifier group (the bracket needs at least two groups).</p><p>Click <strong>Create Tournament</strong> — you land on the tournament detail page.</p><p><img src="/screenshots/booker-tournament-list.png" alt="Tournament list"></p><hr><h2 id="step-2-—-watch-the-bracket-play-out" tabindex="-1">Step 2 — Watch the bracket play out <a class="header-anchor" href="#step-2-—-watch-the-bracket-play-out" aria-label="Permalink to &quot;Step 2 — Watch the bracket play out&quot;">​</a></h2><p>On the tournament detail page you can:</p><ul><li><strong>Start</strong> the tournament (seeds first, if you deferred seeding) — the bracket generates and rounds become pending matches.</li><li><strong>Replace or reorder entrants</strong> before starting — replacements draw from the same eligibility pool.</li><li><strong>Set per-round rules</strong> — pin a stipulation to a specific round.</li><li><strong>Book rounds onto shows</strong> — rounds become segments on the weekly shows; the payoff books on the host show for one-time tournaments.</li></ul><p><img src="/screenshots/booker-tournament-detail-scheduled.png" alt="Tournament detail — scheduled"></p><p>As rounds complete, winners advance automatically. The final (or champion showcase) is the <strong>payoff</strong>.</p><hr><h2 id="step-3-—-recurring-editions-annual-tournaments" tabindex="-1">Step 3 — Recurring editions (annual tournaments) <a class="header-anchor" href="#step-3-—-recurring-editions-annual-tournaments" aria-label="Permalink to &quot;Step 3 — Recurring editions (annual tournaments)&quot;">​</a></h2><p>For an <strong>Annual</strong> tournament paired with a PLE template:</p><ol><li>Book the payoff on the show as usual.</li><li>When the payoff books, the game <strong>creates the next edition automatically</strong> — same format, rules, linked title, gender filter, and entrant count — named with the next Roman numeral.</li><li>The template pairing re-points to the new edition, so next year&#39;s show books the new bracket with no setup.</li></ol><p>Completed earlier editions stay in the list; tick <strong>Show past editions</strong> on the Tournaments page to see the full chain.</p><p><img src="/screenshots/booker-tournament-detail-in-progress.png" alt="Tournament detail — in progress"></p><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./schedule-a-show.html">Schedule a Show</a> — the shows tournaments book onto.</li><li><a href="./report-match-results.html">Report Match Results</a> — resolving the individual matches.</li><li>The auto-generated <a href="./general-manager.html">General Manager</a> guide covers seasons, rivalries, and the wider booking picture.</li></ul>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};